namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post.")
        ]);
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>
    /// Returns notifications added after the given timestamp.
    /// Occasionally generates a new fake notification to simulate activity.
    /// </summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            // ~30 % chance of a new notification each poll cycle.
            if (Random.Shared.Next(0, 3) == 0)
            {
                string[] messages =
                [
                    "Someone liked your photo.",
                    "You have a new follower!",
                    "System maintenance scheduled for tonight.",
                    "Your order has shipped.",
                    "Reminder: team meeting in 15 minutes."
                ];

                _notifications.Add(
                    CreateNotification(messages[Random.Shared.Next(messages.Length)]));
            }

            return Task.FromResult(
                _notifications.Where(n => n.Timestamp > since).ToList());
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

