@code {
    private CancellationTokenSource? _cts;

    /// <summary>
    /// Persisted across the prerender → interactive transition so that
    /// the initial data is not fetched a second time.
    /// </summary>
    [PersistentState]
    public List<Notification>? NotificationList { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when the list wasn't already
        // restored from the prerendered state.
        NotificationList ??= await NotificationService.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during the static prerender pass,
        // so this is the safe place to kick off the polling loop.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        // Start polling from the most recent notification we already have.
        var lastCheck = NotificationList?.MaxBy(n => n.Timestamp)?.Timestamp
                        ?? DateTime.UtcNow;

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                var newer = await NotificationService.GetNotificationsSinceAsync(lastCheck);

                if (newer.Count > 0)
                {
                    NotificationList ??= [];
                    NotificationList.AddRange(newer);
                    lastCheck = newer.Max(n => n.Timestamp);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on dispose — exit cleanly.
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

